import XCTest

final class SettingsTests: XCTestCase {
    func testNavigateToSecurityPrivacy() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()

        func dump(_ path: String) {
            try? app.debugDescription.write(toFile: path, atomically: true, encoding: .utf8)
        }

        let userMenu = app.buttons["User menu"]
        XCTAssertTrue(userMenu.waitForExistence(timeout: 15))
        userMenu.tap()

        let userSettings = app.buttons["User settings"]
        XCTAssertTrue(userSettings.waitForExistence(timeout: 10))
        userSettings.tap()
        Thread.sleep(forTimeInterval: 2)
        dump("/tmp/hier3.txt")

        let secQuery = app.descendants(matching: .any).matching(NSPredicate(format: "label == %@ OR identifier == %@", "Security & Privacy", "Security & Privacy"))
        XCTAssertTrue(secQuery.firstMatch.waitForExistence(timeout: 10))
        secQuery.firstMatch.tap()
        Thread.sleep(forTimeInterval: 2)
        dump("/tmp/hier4.txt")
    }
}

